	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/healthz", wrapper.ReadHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/catalog", wrapper.GetCatalog)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/contacts", wrapper.GetContacts)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/chat/session", wrapper.GetChatSession)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/chat/sync", wrapper.SyncChat)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/chat/history", wrapper.GetChatHistory)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/chat/groups", wrapper.GetChatGroups)
